-- 216: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_216_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_216_guard;
INSERT INTO _migration_216_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_013' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_3' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What distinguishes coiling as a clay-building method?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A solid block is reduced entirely with chisels and rasps","B. A flat slab is folded once and left with an uncompressed seam","C. Successive rolled lengths of clay are joined and compressed to build the wall","D. Liquid slip is poured into an absorbent plaster mould"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Coils are arranged course by course and their contacts are compressed or blended sufficiently for structural continuity. Thickness, moisture and alignment must be controlled as height increases. Therefore the correct answer is C: Successive rolled lengths of clay are joined and compressed to build the wall.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_013' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_216_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_014' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_3' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which sequence best prepares naturally sourced clay for a sound terracotta body?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Dry, crush and dry-sieve the clay, add water, and begin forming as soon as the surface feels plastic","B. Slake the broken clay, dewater it to working stiffness, wedge it, and sieve the body only after it has firmed","C. Remove visible debris, mix grog into the moist clay, wedge it, and form before slaking or sieving the finer body","D. Dry and break it, remove impurities, slake and sieve it, dewater it, add suitable grog if needed, then knead or wedge it"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Systematic preparation produces an even workable body. Dry processing, slaking and sieving remove contaminants; dewatering, optional grog addition and wedging then control consistency and trapped air. Therefore the correct answer is D: Dry and break it, remove impurities, slake and sieve it, dewater it, add suitable grog if needed, then knead or wedge it.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_014' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_216_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_015' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_3' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is grog added to some terracotta clay bodies?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It removes every trapped air pocket without the need for wedging","B. It makes unprepared clay completely plastic without adding water","C. It reduces drying shrinkage, improves dimensional stability and can help thick forms dry more evenly","D. It acts as a glaze that seals the surface before firing"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Grog is ground previously fired clay or ceramic. Its stable particles interrupt shrinkage, add tooth and assist drying, although amount and particle size must suit the desired surface and workability. Therefore the correct answer is C: It reduces drying shrinkage, improves dimensional stability and can help thick forms dry more evenly.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_015' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_216_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_016' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_4' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What makes carving a subtractive sculptural process?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Separate objects are selected and joined into one composition","B. Material is removed from a larger mass to reveal the intended form","C. Molten or fluid material is introduced into a negative mould","D. Prepared clay is added around a supporting armature"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Carving reveals form by planned removal from wood, stone or another solid. Because removed stock cannot simply be replaced, primary masses and finishing allowances must be established carefully. Therefore the correct answer is B: Material is removed from a larger mass to reveal the intended form.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_016' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_013', 'topic_was_sculpture_b004_3', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What distinguishes coiling as a clay-building method?', 'multiple_choice', NULL, '["A. A solid block is reduced entirely with chisels and rasps","B. A flat slab is folded once and left with an uncompressed seam","C. Successive rolled lengths of clay are joined and compressed to build the wall","D. Liquid slip is poured into an absorbent plaster mould"]', 'C', 'Coils are arranged course by course and their contacts are compressed or blended sufficiently for structural continuity. Thickness, moisture and alignment must be controlled as height increases. Therefore the correct answer is C: Successive rolled lengths of clay are joined and compressed to build the wall.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_3', 'Identify', 'AO1', NULL, NULL, 'board_waec');
