INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_015', 'topic_was_sculpture_b004_3', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Why is grog added to some terracotta clay bodies?', 'multiple_choice', NULL, '["A. It removes every trapped air pocket without the need for wedging","B. It makes unprepared clay completely plastic without adding water","C. It reduces drying shrinkage, improves dimensional stability and can help thick forms dry more evenly","D. It acts as a glaze that seals the surface before firing"]', 'C', 'Grog is ground previously fired clay or ceramic. Its stable particles interrupt shrinkage, add tooth and assist drying, although amount and particle size must suit the desired surface and workability. Therefore the correct answer is C: It reduces drying shrinkage, improves dimensional stability and can help thick forms dry more evenly.', 'hard', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_3', 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_016', 'topic_was_sculpture_b004_4', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What makes carving a subtractive sculptural process?', 'multiple_choice', NULL, '["A. Separate objects are selected and joined into one composition","B. Material is removed from a larger mass to reveal the intended form","C. Molten or fluid material is introduced into a negative mould","D. Prepared clay is added around a supporting armature"]', 'B', 'Carving reveals form by planned removal from wood, stone or another solid. Because removed stock cannot simply be replaced, primary masses and finishing allowances must be established carefully. Therefore the correct answer is B: Material is removed from a larger mass to reveal the intended form.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_4', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_013', 'q_was_sculpture_b004_014', 'q_was_sculpture_b004_015', 'q_was_sculpture_b004_016');
